<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { AlertTriangle, ArrowLeft, Camera, ClipboardList, Copy, MapPin, Radio, Ruler } from '@lucide/vue'
import AppStatus from '@/components/AppStatus.vue'
import InspectionMap from '@/components/InspectionMap.vue'
import { problemMessage } from '@/api/client'
import type { HydrantInspectionHistoryItem, HydrantMasterRecord, Page } from '@/api/types'
import { dashboardService } from '@/services/dashboard'
import { evidenceLabel, hydrantAlerts, metadataEntries } from './hydrant-format'

const route=useRoute(),data=ref<HydrantMasterRecord>(),history=ref<Page<HydrantInspectionHistoryItem>>(),loading=ref(true),historyLoading=ref(true),error=ref(''),historyError=ref(''),copied=ref(false)
const date=(value?:string)=>value?new Intl.DateTimeFormat('es-MX',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Hermosillo'}).format(new Date(value)):'No disponible'
const metadata=computed(()=>metadataEntries(data.value?.metadataJson)),alerts=computed(()=>data.value?hydrantAlerts(data.value):[])
const evidencePercent=computed(()=>data.value?.inspectionCount?Math.round(data.value.completeEvidenceCount/data.value.inspectionCount*100):null)
async function copyAccount(){if(!data.value)return;await navigator.clipboard.writeText(data.value.accountNumber);copied.value=true;window.setTimeout(()=>copied.value=false,1500)}
onMounted(async()=>{const id=String(route.params.id);try{data.value=await dashboardService.hydrant(id)}catch(e){error.value=problemMessage(e,'No fue posible cargar el hidrante.')}finally{loading.value=false}try{history.value=await dashboardService.hydrantInspections(id,1,100)}catch(e){historyError.value=problemMessage(e,'No fue posible cargar el historial.')}finally{historyLoading.value=false}})
</script>
<template><div class="content"><div v-if="loading" class="skeleton loading"/><div v-else-if="error" class="error-box" role="alert">{{error}}<br/><RouterLink class="btn" to="/hidrantes">Volver a Hidrantes</RouterLink></div><template v-else-if="data"><nav class="breadcrumbs" aria-label="Breadcrumb"><RouterLink to="/dashboard">Dashboard</RouterLink><span>›</span><RouterLink to="/hidrantes">Hidrantes</RouterLink><span>›</span><b>{{data.accountNumber}}</b></nav>
<header class="record-head"><div class="identity"><RouterLink to="/hidrantes" aria-label="Volver a hidrantes"><ArrowLeft/></RouterLink><div><div class="title-line"><h1>Hidrante <span class="mono">{{data.accountNumber}}</span></h1><AppStatus :status="data.rvStatus"/></div><p>{{data.inspectionCount}} {{data.inspectionCount===1?'revisión':'revisiones'}} · Actualizado {{date(data.updatedAt)}}</p></div></div><div class="actions"><button class="btn" @click="copyAccount"><Copy :size="16"/>{{copied?'Copiado':'Copiar cuenta'}}</button><RouterLink v-if="data.latestInspectionId" class="btn btn--primary" :to="`/revisiones/${data.latestInspectionId}`"><ClipboardList :size="16"/>Ver última revisión</RouterLink></div></header>
<section v-if="alerts.length" class="alerts" aria-label="Alertas objetivas"><span v-for="item in alerts" :key="item"><AlertTriangle :size="16"/>{{item}}</span></section>
<div class="master-grid"><article class="card master"><h2>Información del hidrante</h2><section><h3>Identificación</h3><dl><div><dt>Cuenta</dt><dd class="mono">{{data.accountNumber}}</dd></div><div><dt>Origen</dt><dd>{{data.sourceType==='manual'?'Alta manual':'Catálogo'}}</dd></div><div><dt>Sección</dt><dd>{{data.sectionCode||'No disponible'}}</dd></div><div><dt>UUID</dt><dd class="mono technical">{{data.hydrantId}}</dd></div></dl></section><section v-if="data.installationYear||data.flowLps!=null||data.outletCount!=null||data.installationAngleDeg!=null||data.elevationM!=null"><h3>Información hidráulica y física</h3><dl><div><dt>Año instalación</dt><dd>{{data.installationYear||'No disponible'}}</dd></div><div><dt>Gasto nominal</dt><dd>{{data.flowLps!=null?`${data.flowLps} L/s`:'No disponible'}}</dd></div><div><dt>Salidas</dt><dd>{{data.outletCount??'No disponible'}}</dd></div><div><dt>Ángulo</dt><dd>{{data.installationAngleDeg!=null?`${data.installationAngleDeg}°`:'No disponible'}}</dd></div><div><dt>Elevación</dt><dd>{{data.elevationM!=null?`${data.elevationM} m`:'No disponible'}}</dd></div></dl></section><section v-if="metadata.length"><h3>Metadata adicional</h3><dl><div v-for="[key,value] in metadata" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl><details v-if="data.metadataJson"><summary>JSON técnico original</summary><pre>{{data.metadataJson}}</pre></details></section></article>
<article class="card rv"><h2>Estado de revisión visual</h2><AppStatus :status="data.rvStatus"/><dl><div><dt>Última revisión</dt><dd>{{date(data.lastInspectionAt)}}</dd></div><div><dt>Estado más reciente</dt><dd><AppStatus v-if="data.latestInspectionStatus" :status="data.latestInspectionStatus"/><span v-else>Sin revisión</span></dd></div><div><dt>Técnico</dt><dd>{{data.latestTechnicianName||'No disponible'}}</dd></div><div><dt>Cuadrilla</dt><dd>{{data.latestCrewName||'No disponible'}}</dd></div><div><dt>Evidencia</dt><dd>{{evidenceLabel(data)}}</dd></div><div><dt>Capturas</dt><dd>{{data.inspectionCount?`${data.hasGps?'GPS':'Sin GPS'} · ${data.hasSignal?'Señal':'Sin señal'}`:'No aplica'}}</dd></div></dl></article>
<article class="card stats"><h2>Resumen histórico</h2><div class="stat-grid"><span><b>{{data.inspectionCount}}</b>Total</span><span><b>{{data.submittedCount}}</b>Enviadas</span><span><b>{{data.validatedCount}}</b>Validadas</span><span><b>{{data.rejectedCount}}</b>Rechazadas</span><span><b>{{evidencePercent==null?'—':`${evidencePercent}%`}}</b>Evidencia completa</span><span><b>{{date(data.firstInspectionAt).split(',')[0]}}</b>Primera revisión</span></div></article></div>
<section class="card coordinates"><header><div><h2>Coordenada maestra</h2><p class="muted">Catálogo del hidrante; no es una captura de revisión.</p></div><MapPin/></header><div v-if="data.latitude!=null&&data.longitude!=null" class="map-grid"><InspectionMap :master="{latitude:data.latitude,longitude:data.longitude}"/><dl><div><dt>Latitud</dt><dd class="mono">{{data.latitude}}</dd></div><div><dt>Longitud</dt><dd class="mono">{{data.longitude}}</dd></div><div><dt>Coordenada origen</dt><dd class="mono">{{data.sourceX??'N/D'}}, {{data.sourceY??'N/D'}}</dd></div><div><dt>CRS de origen</dt><dd>{{data.sourceCrs||'No confirmado'}}</dd></div></dl></div><div v-else class="empty-box">No existen coordenadas maestras disponibles.<template v-if="data.sourceX!=null||data.sourceY!=null"><br/><small>Origen: {{data.sourceX??'N/D'}}, {{data.sourceY??'N/D'}} · {{data.sourceCrs||'CRS no confirmado'}}</small></template></div></section>
<section class="card history"><header><div><h2>Historial de revisiones</h2><p class="muted">Más reciente primero. Cada revisión carga su expediente sólo al abrirla.</p></div><b v-if="history">{{history.total}} registros</b></header><div v-if="historyLoading" class="skeleton history-loading"/><div v-else-if="historyError" class="error-box">{{historyError}}</div><div v-else-if="!history?.items.length" class="empty-box">Este hidrante todavía no tiene revisiones visuales.</div><div v-else class="timeline"><article v-for="item in history.items" :key="item.inspectionId"><i/><div class="history-card"><header><strong>Revisión #{{item.revisionNumber}}</strong><AppStatus :status="item.status"/><time>{{date(item.submittedAt||item.startedAt)}}</time></header><p>{{item.technicianName}} · {{item.crewName||'Sin cuadrilla'}}</p><div class="facts"><span><Camera :size="15"/>{{item.mandatoryPhotosCompleted}}/7 obligatorias · {{item.totalPhotos}} total</span><span><MapPin :size="15"/>{{item.hasGps?'GPS':'Sin GPS'}}</span><span><Radio :size="15"/>{{item.hasSignal?'Señal':'Sin señal'}}</span></div><RouterLink :to="`/revisiones/${item.inspectionId}`">Ver revisión</RouterLink></div></article></div></section></template></div></template>
<style scoped>.loading{height:500px}.breadcrumbs{display:flex;gap:8px;font-size:.78rem;color:var(--muted);margin-bottom:14px}.breadcrumbs a{color:#315f9d}.record-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:14px}.identity{display:flex;gap:12px;align-items:flex-start}.identity>a{color:#4d6380;padding-top:5px}.title-line{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.title-line h1{font-size:1.45rem;margin:0}.identity p{color:var(--muted);margin:4px 0}.actions{display:flex;gap:8px}.alerts{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.alerts span{display:flex;align-items:center;gap:5px;color:#8b5b00;background:#fff8df;border:1px solid #ead38a;border-radius:7px;padding:8px 10px;font-size:.78rem}.master-grid{display:grid;grid-template-columns:2fr 1fr;gap:13px}.master{grid-row:span 2;padding:18px}.master h2,.rv h2,.stats h2,.coordinates h2,.history h2{font-size:1rem;margin:0 0 13px}.master section+section{border-top:1px solid #e7ecf2;margin-top:15px;padding-top:13px}.master h3{font-size:.75rem;color:#60738c;text-transform:uppercase}.master dl{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.rv,.stats{padding:18px}.rv>.status{margin-bottom:12px}.rv dl,.coordinates dl{display:grid;grid-template-columns:1fr 1fr;gap:12px}.master dt,.rv dt,.coordinates dt{font-size:.7rem;color:var(--muted)}.master dd,.rv dd,.coordinates dd{margin:3px 0;font-size:.85rem}.technical{font-size:.7rem!important;overflow-wrap:anywhere}details{margin-top:12px}summary{cursor:pointer;font-size:.78rem;color:#315f9d}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fa;padding:10px;border-radius:6px;font-size:.7rem}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.stat-grid span{display:grid;color:var(--muted);font-size:.68rem}.stat-grid b{font-size:1.1rem;color:#192a42}.coordinates,.history{margin-top:13px;padding:18px}.coordinates>header,.history>header{display:flex;justify-content:space-between}.coordinates p,.history p{font-size:.78rem;margin:0}.map-grid{display:grid;grid-template-columns:2fr 1fr;gap:16px}.history-loading{height:180px}.timeline{border-left:2px solid #dae2ec;margin-left:7px}.timeline>article{position:relative;padding:0 0 12px 20px}.timeline>article>i{position:absolute;width:10px;height:10px;border-radius:50%;background:#1763ed;left:-6px;top:18px}.history-card{border:1px solid #dfe6ef;border-radius:8px;padding:13px;background:#fbfcfe}.history-card header{display:flex;align-items:center;gap:9px}.history-card time{margin-left:auto;font-size:.72rem;color:var(--muted)}.history-card p{margin:8px 0}.facts{display:flex;flex-wrap:wrap;gap:12px;font-size:.75rem;color:#536880;margin-bottom:8px}.facts span{display:flex;align-items:center;gap:4px}.history-card a{font-size:.78rem;color:#155bcf;font-weight:650}.status--completed{color:#087a3b;background:#ebfaf2;border-color:#bcead0}.status--pending{color:#805800;background:#fff8e5;border-color:#ead99c}@media(max-width:1000px){.master-grid{grid-template-columns:1fr 1fr}.master{grid-column:1/-1;grid-row:auto}.map-grid{grid-template-columns:1fr}.master dl{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.record-head{display:block}.actions{margin-top:12px;flex-wrap:wrap}.master-grid{grid-template-columns:1fr}.master{grid-column:auto}.master dl,.rv dl,.coordinates dl{grid-template-columns:1fr 1fr}.stat-grid{grid-template-columns:1fr 1fr}.history-card header{align-items:flex-start;flex-wrap:wrap}.history-card time{width:100%;margin:0}.facts{display:grid}.coordinates,.history,.master,.rv,.stats{padding:14px}}@media(max-width:420px){.master dl,.rv dl,.coordinates dl{grid-template-columns:1fr}.actions .btn{width:100%}}</style>
